import { useEffect, useId, useRef, useState } from "react";
import {
  RingCompletion,
  useRingCompletion,
} from "@/components/ring-completion";
import { batchCountdownProgress } from "@/lib/progress";

type Countdown = { startAt: number; endAt: number; observedAt: number };
const countdownCircumference = 2 * Math.PI * 59;

function CountdownArc({
  startAt,
  endAt,
  observedAt,
  frozen = false,
}: Countdown & { frozen?: boolean }) {
  const circle = useRef<SVGCircleElement>(null);
  const [initialOffset] = useState(
    () =>
      countdownCircumference *
      (1 - batchCountdownProgress(startAt, endAt, observedAt)),
  );
  useEffect(() => {
    const element = circle.current;
    if (!element || frozen) return;
    const motion = window.matchMedia("(prefers-reduced-motion: reduce)");
    let frame = 0;
    let interval: ReturnType<typeof setInterval> | undefined;
    let from = Number(element.getAttribute("stroke-dashoffset"));
    let transitionStart = performance.now();
    const draw = (immediate = false) => {
      const target =
        countdownCircumference *
        (1 - batchCountdownProgress(startAt, endAt, Date.now()));
      const fraction =
        immediate || motion.matches
          ? 1
          : Math.min(1, (performance.now() - transitionStart) / 400);
      const eased = 1 - (1 - fraction) ** 3;
      element.setAttribute(
        "stroke-dashoffset",
        String(from + (target - from) * eased),
      );
    };
    const animate = () => {
      draw();
      if (Date.now() < endAt || performance.now() - transitionStart < 400) {
        frame = requestAnimationFrame(animate);
      }
    };
    const synchronize = () => {
      cancelAnimationFrame(frame);
      clearInterval(interval);
      if (document.visibilityState !== "visible") return;
      // Catch up immediately after a hidden tab or a motion preference change.
      draw(true);
      from = Number(element.getAttribute("stroke-dashoffset"));
      transitionStart = performance.now();
      if (motion.matches) interval = setInterval(() => draw(true), 1000);
      else frame = requestAnimationFrame(animate);
    };
    if (document.visibilityState === "visible") {
      if (motion.matches) synchronize();
      else frame = requestAnimationFrame(animate);
    }
    document.addEventListener("visibilitychange", synchronize);
    motion.addEventListener("change", synchronize);
    return () => {
      cancelAnimationFrame(frame);
      clearInterval(interval);
      document.removeEventListener("visibilitychange", synchronize);
      motion.removeEventListener("change", synchronize);
    };
  }, [startAt, endAt, frozen]);
  return (
    <circle
      ref={circle}
      className="countdown-arc"
      cx="85"
      cy="85"
      r="59"
      fill="none"
      stroke="var(--queued)"
      strokeWidth="3"
      strokeLinecap="butt"
      strokeDasharray={countdownCircumference}
      strokeDashoffset={initialOffset}
    />
  );
}
export { estimateSeconds } from "@/lib/progress";
export function ProgressRing({
  sent,
  queued,
  failed,
  review = 0,
  seconds,
  draft = false,
  countdown,
}: {
  sent: number;
  queued: number;
  failed: number;
  review?: number;
  seconds: number;
  draft?: boolean;
  countdown?: Countdown;
}) {
  const gradientId = useId();
  const segments = [
    { label: "Sent", count: sent, color: "var(--success)" },
    { label: "Queued", count: queued, color: "var(--queued)" },
    { label: "Failed", count: failed, color: "var(--error)" },
    ...(review
      ? [{ label: "Needs review", count: review, color: "var(--body)" }]
      : []),
  ];
  const total = segments.reduce((sum, segment) => sum + segment.count, 0);
  const idle = draft && total === 0;
  const complete =
    !draft && sent > 0 && queued === 0 && failed === 0 && review === 0;
  const completion = useRingCompletion(
    complete,
    queued > 0 ? countdown : undefined,
  );
  const circumference = 2 * Math.PI * 70;
  const nonempty = segments.filter((segment) => segment.count > 0).length;
  let offset = 0;
  const center = queued
    ? !draft && seconds === 0
      ? "Sending"
      : `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`
    : review
      ? "Review"
      : failed
        ? "Finished"
        : sent
          ? "Done"
          : "0:00";
  return (
    <div
      className={`flex flex-wrap items-center gap-[22px]${draft ? " draft-progress" : ""}`}
      aria-label={`Estimated send progress: ${sent} sent, ${queued} ${draft ? "selected" : "queued"}, ${failed} failed, ${review} need review`}
    >
      <span className="sr-only" role="status">
        {complete ? "Batch complete. All emails sent." : ""}
      </span>
      <div className="progress-ring shrink-0 relative size-[170px]">
        <svg
          width="170"
          height="170"
          viewBox="0 0 170 170"
          className="-rotate-90"
          aria-hidden="true"
        >
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="1" y2="1">
              <stop
                offset="0%"
                stopColor="var(--progress-fill, var(--accent))"
              />
              <stop
                offset="100%"
                stopColor="var(--progress-fill, var(--accent2))"
              />
            </linearGradient>
          </defs>
          <circle
            className={idle ? "progress-arc" : undefined}
            cx="85"
            cy="85"
            r="70"
            fill="none"
            stroke={idle ? `url(#${gradientId})` : "var(--ring-track)"}
            strokeWidth={idle ? 11 : 12}
          />
          {!complete &&
            segments.map((segment) => {
              const length = total
                ? (segment.count / total) * circumference
                : 0;
              const gap = nonempty > 1 ? Math.min(14, length * 0.3) : 0;
              const start = offset;
              offset += length;
              return (
                <circle
                  key={segment.label}
                  cx="85"
                  cy="85"
                  r="70"
                  fill="none"
                  stroke={segment.color}
                  strokeWidth="12"
                  strokeLinecap="round"
                  strokeDasharray={`${Math.max(0, length - gap)} ${circumference}`}
                  strokeDashoffset={-start - gap / 2}
                  style={{ opacity: segment.count ? 1 : 0 }}
                />
              );
            })}
          {completion.countdown && (
            <g
              className={
                complete
                  ? "completion-countdown-exit opacity-[0] invisible"
                  : undefined
              }
            >
              <CountdownArc {...completion.countdown} frozen={complete} />
            </g>
          )}
        </svg>
        {complete && (
          <RingCompletion
            size={170}
            radius={70}
            strokeWidth={12}
            animate={completion.animate}
          />
        )}
        {!complete && (
          <div className="absolute inset-0 mx-auto grid w-[110px] content-center text-center">
            <b
              className={`timer-value font-num font-semibold ${center === "Sending" ? "text-[18px]" : "text-[26px]"} tracking-[-.02em] tabular-nums`}
            >
              {center}
            </b>
            <span className="text-[10px] uppercase tracking-wide text-body">
              {queued
                ? !draft && seconds === 0
                  ? "Please be patient"
                  : "est. left"
                : review
                  ? "needs review"
                  : failed
                    ? "with failures"
                    : sent
                      ? "all sent"
                      : "est. time left"}
            </span>
          </div>
        )}
      </div>
      <div className="grid gap-2 text-[13px]">
        {segments.map((segment) => (
          <div key={segment.label} className="flex items-center gap-2">
            <span
              className="size-2.5 rounded-full"
              style={{ background: segment.color }}
              aria-hidden="true"
            />
            {draft && segment.label === "Queued" ? "Selected" : segment.label} ·{" "}
            {segment.count}
          </div>
        ))}
      </div>
    </div>
  );
}
